ids = ["LY-614","LY-615","LY-616","LY-617","LY-618","LY-619","LY-620","LY-621","LY-622","LY-623","LY-624","LY-625","LY-626","LY-627","LY-628","LY-629","MH-001","MH-002","MH-003","MH-006"]
assert set(P.keys()) == set(ids), (set(ids)-set(P.keys()))
total = 0
for cid in ids:
    obj = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"], "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
    data = json.dumps(obj, ensure_ascii=False, indent=1).encode("utf-8")
    (OUT / f"{cid}.json").write_bytes(data)
    total += len(data)
# per-file self-verify: exact open by id list only (no directory enumeration)
n = 0
for cid in ids:
    obj = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
    assert obj["case_id"] == cid
    for k in ("case_id","prediction_text","basis","confidence","trigger"):
        assert k in obj, (cid, k)
    assert 0 <= obj["confidence"] <= 1
    for k in ("changed_main","reserve_used","disputed","reason"):
        assert k in obj["trigger"], (cid, k)
    n += 1
assert n == 20
cm = sum(1 for c in ids if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in ids if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in ids if P[c]["trigger"]["disputed"])
print(f"written={n} total_bytes={total} changed_main={cm} reserve_used={ru} disputed={di}")
